using namespace stereoforge;using json=nlohmann::json;using Clock=std::chrono::steady_clock;
inline void check(bool v,const char* m){if(!v)throw std::invalid_argument(m);}
inline uint32_t number(std::string const& s){uint32_t out=0;auto [end,error]=std::from_chars(s.data(),s.data()+s.size(),out);check(error==std::errc{}&&end==s.data()+s.size(),"invalid integer option");return out;}
inline void write(std::filesystem::path const& path,const void* bytes,size_t size){int fd=::open(path.c_str(),O_WRONLY|O_CREAT|O_EXCL|O_CLOEXEC,0666);check(fd>=0,"fresh exclusive output required");size_t at=0;while(at<size){auto n=::write(fd,static_cast<char const*>(bytes)+at,size-at);if(n<0&&errno==EINTR)continue;if(n<=0){::close(fd);throw std::runtime_error("output write failed");}at+=size_t(n);}check(::close(fd)==0,"output close failed");}
// Nearest-rank percentile: ceil(p*N/100)-1, including even-size medians.
inline size_t percentile_index(size_t n,unsigned p){
    if(n==0||p==0||p>100)throw std::invalid_argument("invalid percentile population/rank");
    return (n/100)*p+((n%100)*p+99)/100-1;
}
inline json summary(std::vector<double> values){std::sort(values.begin(),values.end());auto at=[&](unsigned p){return values[percentile_index(values.size(),p)];};return {{"mean",std::accumulate(values.begin(),values.end(),0.)/values.size()},{"p50",at(50)},{"p95",at(95)},{"p99",at(99)},{"max",values.back()}};}
struct Options {std::map<std::string,std::string> values;bool validation=false;Options(int argc,char** argv){for(int i=1;i<argc;++i){std::string key=argv[i];if(key=="--validation"){validation=true;continue;}check(key=="--coarse-manifest"||key=="--target-manifest"||key=="--output"||key=="--dump-prefix"||key=="--frames"||key=="--warmup"||key=="--radius"||key=="--subpixel"||key=="--variant"||key=="--slots"||key=="--wave-size","unknown refinement option");check(++i<argc,"missing option value");check(values.emplace(key,argv[i]).second,"duplicate option");}check(values.contains("--coarse-manifest")&&values.contains("--target-manifest")&&values.contains("--output"),"coarse/target manifests and output required");}uint32_t number_or(char const* key,uint32_t fallback)const{return values.contains(key)?number(values.at(key)):fallback;}};
struct Prepared {
    DaxaPreprocessFixture coarse,target;std::string coarse_hash,target_hash;CaptureLease source;DaxaDepthConfig depth;DaxaRefinementConfig refinement;
    Prepared(Options const& o):coarse(load_daxa_preprocess_fixture(o.values.at("--coarse-manifest"))),target(load_daxa_preprocess_fixture(o.values.at("--target-manifest"))){coarse_hash=daxa_preprocess_file_sha256(o.values.at("--coarse-manifest"));target_hash=daxa_preprocess_file_sha256(o.values.at("--target-manifest"));check(coarse.capture_sha256==target.capture_sha256&&coarse.record_ordinal==target.record_ordinal,"coarse and target must bind identical original record");validate_daxa_refinement_geometry(coarse.rectification,target.rectification);auto replay=packed_replay_source(coarse.capture_directory);auto frame=std::make_shared<CaptureFrame>();for(uint64_t i=0;i<=coarse.record_ordinal;++i)check(replay(*frame,std::chrono::milliseconds(100))==CaptureSourceStatus::recorded_frame,"missing replay record");source=frame;coarse.rectification.validate_source(*source);target.rectification.validate_source(*source);depth.stereo={coarse.rectification.width,coarse.rectification.height,64,4,8,32,true};depth.slots=o.number_or("--slots",2);depth.required_wave_size=o.number_or("--wave-size",32);depth.validate();refinement.slots=depth.slots;refinement.radius=o.number_or("--radius",4);auto subpixel=o.number_or("--subpixel",0);check(subpixel<=1,"subpixel must be0/1");refinement.subpixel=subpixel;refinement.validate();}
    void verify(Options const& o)const{check(daxa_preprocess_file_sha256(o.values.at("--coarse-manifest"))==coarse_hash&&daxa_preprocess_file_sha256(o.values.at("--target-manifest"))==target_hash&&daxa_preprocess_file_sha256(coarse.capture_directory/"capture.sfp")==coarse.capture_sha256&&daxa_preprocess_file_sha256(target.capture_directory/"capture.sfp")==target.capture_sha256,"input bytes changed during run");}
    json report()const{json spirv=json::object();for(auto entry:{"rectify","census","match","lr","metric"}){auto path=std::filesystem::path(DaxaRefinement::shader_directory())/(std::string("daxa-refinement-")+entry+".spv");spirv[entry]=daxa_preprocess_file_sha256(path);}return {{"schema","stereoforge.daxa_refinement.v1"},{"percentile_policy","nearest_rank_ceil_p_times_N_minus1"},{"refinement_shader_compiler",{{"version",DaxaRefinement::compiler_version()},{"commit",DaxaRefinement::compiler_commit()},{"package_sha256",DaxaRefinement::compiler_package_sha256()},{"compiler_sha256",DaxaRefinement::compiler_sha256()},{"floating_point_mode","precise"},{"spirv_sha256",spirv}}},{"coarse_shader_compiler",{{"version",SF_DAXA_SLANG_VERSION},{"compiler_sha256",SF_DAXA_COMPILER_SHA256}}},{"scope","static_repeated_original_record; no_live_or_quality_claim"},{"width",target.rectification.width},{"height",target.rectification.height},{"coarse_width",coarse.rectification.width},{"coarse_height",coarse.rectification.height},{"coarse_disparities",64},{"disparities",refinement.disparities},{"radius",refinement.radius},{"subpixel",refinement.subpixel},{"recovery",false},{"prior_confidence_floor",refinement.prior_confidence_floor},{"max_coarse_span",refinement.max_coarse_span},{"min_margin",refinement.min_margin},{"lr_tolerance",refinement.lr_tolerance},{"estimator","independent-local-census"},{"right_reference_mode","independent-local-census"},{"lr_dependency","independent-references"},{"coarse_manifest_sha256",coarse_hash},{"target_manifest_sha256",target_hash},{"capture_sha256",coarse.capture_sha256},{"record_ordinal",coarse.record_ordinal},{"source_id",source->frame_id},{"target_rectified_identity",target.rectification.rectified_identity},{"coarse_rectified_identity",coarse.rectification.rectified_identity},{"shader_identity",DaxaRefinement::shader_identity()},{"float_qualification","unqualified; exact masks and operation-specific error bounds required"},{"metric_calibration",{{"fx",target.rectification.metric_calibration().fx},{"baseline_m",target.rectification.metric_calibration().baseline_m},{"cx_offset",target.rectification.metric_calibration().cx_offset}}}};}
};
inline json dump(DaxaRefinementReadback const& r,std::string const& prefix){json files=json::object();auto plane=[&](char const* name,auto const& values){std::string path=prefix+"."+name;write(path,values.data(),values.size()*sizeof(typename std::remove_reference_t<decltype(values)>::value_type));files[name]={{"path",path},{"sha256",daxa_preprocess_file_sha256(path)},{"elements",values.size()}};};
plane("disparity.f32",r.disparity);plane("confidence.f32",r.confidence);plane("validity.u32",r.validity);plane("depth.f32",r.depth);plane("metric_confidence.f32",r.metric_confidence);plane("metric_validity.u32",r.metric_validity);plane("provenance.u32",r.provenance);plane("source_ids.i64",r.source_ids);plane("age_ns.i64",r.age_ns);plane("prediction.f32",r.prediction);plane("prediction_validity.u32",r.prediction_validity);plane("lower.u32",r.lower);plane("upper.u32",r.upper);plane("reason.u32",r.reason);plane("method.u32",r.method);plane("winner.u32",r.winner);plane("best_cost.u32",r.best_cost);plane("second_cost.u32",r.second_cost);plane("supported_candidates.u32",r.supported_candidates);plane("evaluated_candidates.u32",r.evaluated_candidates);plane("subpixel_applied.u32",r.subpixel_applied);plane("raw_disparity.f32",r.raw_disparity);plane("raw_confidence.f32",r.raw_confidence);plane("raw_validity.u32",r.raw_validity);plane("census.u32",r.census);plane("census_validity.u32",r.census_validity);plane("luma.u32",r.luma);plane("support.u32",r.support);plane("rectified_left.u32",r.rectified_rgb[0]);plane("rectified_right.u32",r.rectified_rgb[1]);return files;}
